'use strict';
const DISCLAIMER="Disclaimer: The content of this email is confidential and intended for the recipient specified in message only. It is strictly forbidden to share any part of this message with any third party, without a written consent of the sender. If you received this message by mistake, please reply to this message and follow with its deletion, so that we can ensure such a mistake does not occur in the future.";
const BANNERS={"midnight":{"src":"data:image/jpeg;base64,","file":"assets/ngsr-banner-midnight.jpg","alt":"Bringing seafarers home. With dignity. With care. www.ngsr.co.za"},"bronze":{"src":"data:image/jpeg;base64,","file":"assets/ngsr-banner-bronze.jpg","alt":"Every journey deserves care. Explore our approach. www.ngsr.co.za"},"homeward":{"src":"data:image/jpeg;base64,","file":"assets/ngsr-banner-homeward.jpg","alt":"Across borders. With dignity. Discover NGSR. www.ngsr.co.za"}};
const EMBEDDED_LOGO='data:image/png;base64,';
const ids=['name','title','accreditation','phone','email','website'];
const $=id=>document.getElementById(id);
const defaults=Object.fromEntries(ids.map(id=>[id,$(id).value]));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const values=()=>Object.fromEntries(ids.map(id=>[id,$(id).value.trim()]));
function websiteUrl(s){try{const u=new URL(/^https?:\/\//i.test(s)?s:'https://'+s);return ['https:','http:'].includes(u.protocol)&&u.hostname.includes('.')&&!u.username&&!u.password?u.href:'';}catch{return '';}}
function phoneUrl(s){return s.replace(/\(0\)/g,'').replace(/[^+\d]/g,'');}
function hostedAsset(path,embedded){try{if(['https:','http:'].includes(window.location.protocol))return new URL(path,document.baseURI).href;}catch{}return embedded;}
function logo(){const s=$('logoUrl').value.trim();try{const u=new URL(s);if(u.protocol==='https:'&&!u.username&&!u.password)return u.href;}catch{}return hostedAsset('assets/ngsr-logo.png',EMBEDDED_LOGO);}
function link(text,href,color){return `<a href="${esc(href)}" style="color:${color};text-decoration:none;">${esc(text)}</a>`;}
function selectedBanner(){return BANNERS[document.querySelector('input[name="bannerChoice"]:checked')?.value]||BANNERS.midnight;}
function banner(){const item=selectedBanner();return hostedAsset(item.file,item.src);}
function signatureHTML(){const v=values();const contacts=[];if(v.phone)contacts.push('T:&nbsp;' +link(v.phone,'tel:'+phoneUrl(v.phone),'#626262'));if(v.email)contacts.push('E:&nbsp;' +link(v.email,'mailto:'+encodeURIComponent(v.email).replace(/%40/g,'@'),'#626262'));const url=websiteUrl(v.website);return `<table role="presentation" width="480" cellpadding="0" cellspacing="0" border="0" style="width:480px;border-collapse:collapse;mso-table-lspace:0pt;mso-table-rspace:0pt;font-family:'Canva Sans',Arial,Helvetica,sans-serif;color:#000000;background-color:#ffffff;"><tr><td style="font-family:'Canva Sans',Arial,Helvetica,sans-serif;font-size:10pt;font-style:italic;line-height:14pt;color:#626262;padding:0 0 14px;">Should you have any queries, please do not hesitate to contact me.</td></tr><tr><td style="font-family:'Canva Sans',Arial,Helvetica,sans-serif;font-size:10pt;font-style:italic;line-height:14pt;color:#626262;padding:0 0 14px;">Kind regards,</td></tr><tr><td style="font-family:'Canva Sans',Arial,Helvetica,sans-serif;font-size:14pt;font-weight:700;line-height:18pt;mso-line-height-rule:at-least;padding:0;">${esc(v.name)}</td></tr>${v.title?`<tr><td style="font-family:'Canva Sans',Arial,Helvetica,sans-serif;font-size:10pt;line-height:14pt;color:#a47250;padding:4px 0 0;">${esc(v.title)}</td></tr>`:''}${v.accreditation?`<tr><td style="font-family:'Canva Sans',Arial,Helvetica,sans-serif;font-size:9pt;line-height:12pt;color:#626262;padding:3px 0 0;">${esc(v.accreditation)}</td></tr>`:''}<tr><td style="padding:14px 0 20px;"><img src="${esc(logo())}" width="175" height="41" alt="NGSR Seafarer Repatriation" border="0" style="display:block;width:175px;height:41px;border:0;"></td></tr>${contacts.length?`<tr><td style="font-family:'Canva Sans',Arial,Helvetica,sans-serif;font-size:10pt;line-height:14pt;color:#626262;padding:0;">${contacts.join('&nbsp;&nbsp;|&nbsp;&nbsp;')}</td></tr>`:''}${v.website?`<tr><td style="font-family:'Canva Sans',Arial,Helvetica,sans-serif;font-size:10pt;line-height:14pt;color:#a47250;padding:4px 0 0;">${url?link(v.website,url,'#a47250'):esc(v.website)}</td></tr>`:''}<tr><td style="padding:14px 0 0;"><a href="https://www.ngsr.co.za" style="text-decoration:none;"><img src="${banner()}" width="480" height="152" border="0" alt="${esc(selectedBanner().alt)}" style="display:block;width:480px;height:152px;border:0;"></a></td></tr><tr><td style="padding:10px 0 0;"><table role="presentation" width="480" cellpadding="0" cellspacing="0" border="0" style="width:480px;border-collapse:collapse;"><tr><td style="font-family:'Canva Sans',Arial,Helvetica,sans-serif;font-size:8pt;line-height:11pt;color:#666666;text-align:left;padding:0;">${esc(DISCLAIMER)}</td></tr></table></td></tr></table>`;}
function render(){$('signature').innerHTML=signatureHTML();$('status').textContent='';$('downloadBanner').href=selectedBanner().file;$('downloadBanner').download=selectedBanner().file.split('/').pop();}
function selectSignature(){const range=document.createRange();range.selectNodeContents($('signature'));const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);}
function validate(){if(!$('details').reportValidity())return false;const v=values();if(!v.name){$('status').textContent='Enter your full name before copying.';$('name').focus();return false;}if(v.website&&!websiteUrl(v.website)){$('status').textContent='Enter a valid website, such as www.ngsr.co.za.';return false;}const s=$('logoUrl').value.trim();if(s&&!/^https:\/\//i.test(s)){$('status').textContent='Use a public HTTPS URL for the logo, or leave it blank.';return false;}return true;}
function plainText(){const v=values();return ['Should you have any queries, please do not hesitate to contact me.','','Kind regards,',v.name,v.title,v.accreditation,'NGSR | Seafarer Repatriation',[v.phone,v.email].filter(Boolean).join(' | '),v.website,'',DISCLAIMER].filter(Boolean).join('\n');}
async function copySignature(){if(!validate())return;const html=signatureHTML();const text=plainText();try{if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined')throw Error('Use selection');await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([html],{type:'text/html'}),'text/plain':new Blob([text],{type:'text/plain'})})]);$('status').textContent='Signature copied. Paste into Outlook, then check the logo.';}catch{selectSignature();try{if(!document.execCommand('copy'))throw Error('Manual copy');$('status').textContent='Signature copied. Paste into Outlook, then check the logo.';}catch{$('status').textContent='Signature selected. Press Ctrl + C or ⌘ + C, then paste into Outlook.';}}}
$('details').addEventListener('submit',e=>e.preventDefault());
ids.forEach(id=>$(id).addEventListener('input',render));$('logoUrl').addEventListener('input',render);document.querySelectorAll('input[name="bannerChoice"]').forEach(input=>input.addEventListener('change',render));
$('copy').addEventListener('click',copySignature);
$('select').addEventListener('click',()=>{selectSignature();$('status').textContent='Press Ctrl + C or ⌘ + C to copy the selected signature.';});
$('reset').addEventListener('click',()=>{ids.forEach(id=>$(id).value=defaults[id]);$('logoUrl').value='';$('banner-midnight').checked=true;render();});
$('html').addEventListener('click',()=>{if(!validate())return;const html='<!doctype html><html><head><meta charset="utf-8"><title>NGSR Signature</title></head><body>'+signatureHTML()+'</body></html>';const url=URL.createObjectURL(new Blob([html],{type:'text/html'}));const a=document.createElement('a');a.href=url;a.download='NGSR-'+(values().name.replace(/[^a-z0-9]+/gi,'-')||'signature')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='HTML downloaded. Open it in a browser to select and copy your signature.';});
$('banner-midnight').checked=true;
render();
